export function orchestrateVoiceScene(input){
  const _scenes={
    'morning':['turn on lights','start coffee machine'],
    'night':['turn off lights','close blinds'],
    'away':['set temperature to 18 degrees','close garage']
  };
  let _cmds=[];
  if(typeof input==='string') _cmds=[input];
  else if(Array.isArray(input)) _cmds=input.slice();
  else if(input&&typeof input==='object'){
    if(Array.isArray(input.commands)) _cmds=input.commands.slice();
    else if(typeof input.scene==='string'&&_scenes[input.scene]) _cmds=_scenes[input.scene].slice();
  }
  const words=[
    'turn','allumer','on','sur','off','éteint','lights','lumières',
    'start','démarrer','coffee','café','machine','machine','heater','chauffage',
    'open','ouvrir','blinds','stores','close','fermer','garage','garage',
    'set','régler','temperature','température','to','à','degrees','degrés'
  ];
  const table=[];
  for(let i=0;i<4;i++){
    const row=[];
    for(let j=0;j<4;j++){
      const idx=(i*4+j)*2;
      row.push([words[idx],words[idx+1]]);
    }
    table.push(row);
  }
  const sum=s=>[...s].reduce((a,c)=>(a<<1)^c.charCodeAt(0),0);
  const translate=phr=>phr.split(' ').map(w=>{
    const a=(sum(w)^w.length);
    const x=a%4,y=(a>>2)%4;
    const p=table[x][y];
    return p[0]===w?p[1]:w;
  }).join(' ');
  const order=Array.from({length:_cmds.length},(_,i)=>i)
    .sort((a,b)=>(sum(_cmds[b])^b)-(sum(_cmds[a])^a));
  const orchestrated=order.map(i=>({source:_cmds[i],translation:translate(_cmds[i])}));
  const out={orchestrated};
  if(input&&input.scene) out.scene=input.scene;
  return out;
}
