def hamming_distance(strand1, strand2):
    """Calculates the Hamming distance between two DNA strands."""

    strand1 = strand1.strip()
    strand2 = strand2.strip()

    valid_chars = {'A', 'C', 'G', 'T'}

    if len(strand1) != len(strand2):
        return 'Error: DNA strands must be of equal length.'

    for char in strand1:
        if char not in valid_chars:
            return 'Error: Strand 1 contains invalid DNA characters.'
    for char in strand2:
        if char not in valid_chars:
            return 'Error: Strand 2 contains invalid DNA characters.'

    distance = 0
    for i in range(len(strand1)):
        if strand1[i] != strand2[i]:
            distance += 1

    return distance

if __name__ == "__main__":
