    fn adaptive_speed_limit_calculator(json_input: Value) -> Value {
    let road_conditions = json_input["road_conditions"].as_array().unwrap_or(&vec![]).clone();
    let weather_factors = json_input["weather_factors"].as_array().unwrap_or(&vec![]).clone();
    let base_speed_limit = json_input["base_speed_limit"].as_i64().unwrap_or(60);
    let road_segment = json_input["road_segment"].as_str().unwrap_or("UNKNOWN");

    let mut segment_encoding = vec![];
    for (i, ch) in road_segment.chars().enumerate() {
        let encoded = ((ch as i64) + (i as i64) * 7) % 256;
        segment_encoding.push(encoded);
    }

    let mut state_matrix = vec![vec![0; 8]; 8];
    for (i, condition) in road_conditions.iter().enumerate().take(8) {
        let condition_str = condition.as_str().unwrap_or("");
        let row = i % 8;

        for (j, ch) in condition_str.chars().enumerate().take(8) {
            let col = j % 8;
            state_matrix[row][col] = ((ch as i64) * (i as i64 + 1) * (j as i64 + 1)) % 16;
        }
    }

    for (i, factor) in weather_factors.iter().enumerate().take(8) {
        let factor_name = factor["name"].as_str().unwrap_or("");
        let factor_value = factor["value"].as_i64().unwrap_or(0);

        for j in 0..8 {
            if i < 8 {
                let modifier = match factor_name {
                    "visibility" => factor_value / 10,
                    "precipitation" => factor_value / 5,
                    "wind" => factor_value / 15,
                    "temperature" => factor_value / 20,
                    _ => factor_value / 25,
                };

                state_matrix[i][j] = (state_matrix[i][j] + modifier) % 16;
            }
        }
    }

    let mut safety_score = 0;
    for i in 0..8 {
        for j in 0..8 {
            safety_score += state_matrix[i][j] * (1 << (i + j) % 6);
        }
    }
    safety_score %= 1000;

    for (i, code) in segment_encoding.iter().enumerate() {
        safety_score = (safety_score + (code * (i as i64 + 1))) % 1000;
    }

    let speed_adjustment = if safety_score < 200 {
        0
    } else if safety_score < 400 {
        -5
    } else if safety_score < 600 {
        -10
    } else if safety_score < 800 {
        -15
    } else {
        -20
    };

    let mut adjusted_speed_limit = base_speed_limit;
    adjusted_speed_limit += speed_adjustment;
    adjusted_speed_limit -= (road_segment.len() as i64 % 7) * 2;

    let ascii_sum: i64 = road_segment.chars().map(|c| c as i64).sum();
    adjusted_speed_limit -= ascii_sum % 10;
    adjusted_speed_limit = adjusted_speed_limit.max(20).min(130);

    let advisory_code = (safety_score / 100) as usize % 4;
    let advisory_messages = vec![
        "Favorable driving conditions",
        "Moderate conditions, drive with care",
        "Caution advised, reduce speed",
        "Extreme caution, hazardous conditions"
    ];
    let advisory_message = advisory_messages[advisory_code];

    json!({
        "adjusted_speed_limit": adjusted_speed_limit,
        "road_segment": road_segment,
        "advisory_message": advisory_message,
        "safety_score": safety_score
    })
}

