        result["meta"] = {
            "key_count": len(d),
            "avg_key_length": sum(key_lengths) // max(1, len(key_lengths)),
            "complexity": (len(d) * sum(key_lengths)) % 100
        }
        return result

    # Main dispatch based on input type
