Here's a Java implementation of the `convertTo1D` method:

```java
public class ArrayConverter {

    public static int[] convertTo1D(int[][] twoDArray) {
        int rows = twoDArray.length;
        int cols = twoDArray[0].length; // Assuming all rows have the same length

        int[] oneDArray = new int[rows * cols];
        int index = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                oneDArray[index++] = twoDArray[i][j];
            }
        }

        return oneDArray;
    }

    public static void main(String[] args) {
        int[][] testArray1 = {{1, 2}, {3, 4}};
        int[] result1 = convertTo1D(testArray1);
        System.out.println("Test 1: " + java.util.Arrays.toString(result1)); // Output: [1, 2, 3, 4]

        int[][] testArray2 = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[] result2 = convertTo1D(testArray2);
        System.out.println("Test 2: " + java.util.Arrays.toString(result2)); // Output: [1, 2, 3, 4, 5, 6, 7, 8, 9]

        int[][] testArray3 = {{1}};
        int[] result3 = convertTo1D(testArray3);
        System.out.println("Test 3: " + java.util.Arrays.toString(result3)); // Output: [1]
    }
}
