Finally, if `num` is a positive integer, the function employs recursion. It calculates the factorial by multiplying `num` with the result of calling `factorial_recursive` on `num - 1`. This continues until the base case (num = 0) is reached, at which point the recursion unwinds, and the final factorial value is computed. The main part of the script takes an integer input from the user, calls `factorial_recursive` to calculate its factorial, and then presents the result.

To solve this, we can utilize a difference array technique. Initialize a difference array `diff` of size `n + 1`, setting all elements to zero. For each operation (l, r, d), increment `diff[l]` by `d` and decrement `diff[r + 1]` by `d`. This efficiently encodes the cumulative effect of each operation.

Next, process the queries. For each query (x, y), apply operations from x to y inclusive.  We don't actually *apply* the operations immediately. Instead, we consider the cumulative effect of these operations.

After all queries are processed, reconstruct the original array.  The array `a` is obtained by calculating the prefix sum of the `diff` array. Specifically, `a[i] = a[i-1] + diff[i]` for i from 1 to n, with `a[0]` initialized to 0.

Finally, output the updated array `a`. The key is understanding that the difference array allows us to represent a series of range updates in a compact form, and the prefix sum reconstructs the final array values. This approach efficiently handles multiple queries and range updates, avoiding redundant computations.



```cpp
#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<tuple<int, int, int>> operations(m);
    for (int i = 0; i < m; ++i) {
        cin >> get<0>(operations[i]) >> get<1>(operations[i]) >> get<2>(operations[i]);
    }

    vector<pair<int, int>> queries(k);
    for (int i = 0; i < k; ++i) {
        cin >> queries[i].first >> queries[i].second;
    }

    vector<int> diff(n + 1, 0);

    for (int i = 0; i < m; ++i) {
        int l = get<0>(operations[i]);
        int r = get<1>(operations[i]);
        int d = get<2>(operations[i]);
        diff[l - 1] += d;
        if (r < n) {
            diff[r] -= d;
        }
    }

    for (int i = 0; i < k; ++i) {
        int x = queries[i].first;
        int y = queries[i].second;

        for (int j = x - 1; j < y; ++j) {
            int l = get<0>(operations[j]);
            int r = get<1>(operations[j]);
            int d = get<2>(operations[j]);
            diff[l - 1] += d;
            if (r < n) {
                diff[r] -= d;
            }
        }
    }

    vector<int> result(n);
    result[0] = a[0] + diff[0];
    for (int i = 1; i < n; ++i) {
        result[i] = result[i - 1] + diff[i];
    }

    for (int i = 0; i < n; ++i) {
        cout << result[i] << (i == n - 1 ? "" : " ");
    }
    cout << endl;

    return 0;
}
