def find_primes(n):
    """
    Finds all prime numbers up to and including n.

    Args:
        n: An integer.

    Returns:
        A set containing all prime numbers from 2 up to n (inclusive).
    """

    if n < 2:
        return set()

    primes = set()
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    for i in range(2, n + 1):
        if is_prime[i]:
            primes.add(i)

    return primes

if __name__ == "__main__":
    n = int(input())
    prime_set = find_primes(n)
    print(prime_set)
```

