def calculate_fibonacci_and_factorial(n):
    """
    Calculates the Fibonacci number at index n and the factorial of that Fibonacci number.

    Args:
        n: An integer representing the index in the Fibonacci sequence.

    Returns:
        A tuple containing the Fibonacci number at index n and the factorial of that number.
    """

    if n <= 0:
        fibonacci_number = 0
    else:
        a, b = 0, 1
        for _ in range(n):
            a, b = b, a + b
        fibonacci_number = a

    if fibonacci_number == 0:
        factorial_result = 1
    else:
        factorial_result = 1
        for i in range(1, fibonacci_number + 1):
            factorial_result *= i

    return (fibonacci_number, factorial_result)
```

