def special_factorial(n):
    """
    Calculates a special factorial based on whether the input is even or odd.
    """
    if not isinstance(n, int):
        return "The input must be an integer."
    if n < 0:
        return "The input must be a non-negative integer."

    if n == 0:
        return 1

    if n % 2 == 0:  # Even number
        result = 1
        for i in range(n, 0, -2):
            result *= i
        return result
    else:  # Odd number
        result = 1
        for i in range(n, 0, -2):
            result *= i
        return result

