def prime_factors_count(n):
    """
    Calculates the prime factors of a positive integer and their counts.

    Args:
        n: An integer greater than 1.

    Returns:
        A dictionary where keys are prime factors and values are their counts.
        Returns 'Invalid input. Please provide an integer.' for invalid inputs.
    """
    try:
        n = int(n)
    except (ValueError, TypeError):
        return 'Invalid input. Please provide an integer.'

    if n <= 1:
        return 'Invalid input. Please provide an integer.'

    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            if d in factors:
                factors[d] += 1
            else:
                factors[d] = 1
            n //= d
        d += 1

    if n > 1:
        if n in factors:
            factors[n] += 1
        else:
            factors[n] = 1

    return factors
