class Stack:
    def __init__(self, capacity):
        self.capacity = capacity
        self.items = [None] * capacity
        self.top = -1

    def push(self, x):
        if self.top == self.capacity - 1:
            print("Stack is full. Cannot push more items.")
        else:
            self.top += 1
            self.items[self.top] = x

    def pop(self):
        if self.top == -1:
            print("Stack is empty. Cannot pop an item.")
        else:
            item = self.items[self.top]
            self.items[self.top] = None  # Optional: Clear the popped item
            self.top -= 1
            print(item)

    def peek(self):
        if self.top == -1:
            print("Stack is empty. Nothing to peek.")
        else:
            print(self.items[self.top])


def main():
    stack = Stack(10)
    while True:
        try:
            line = input()
            parts = line.split()
            command = parts[0]

            if command == "push":
                x = int(parts[1])
                stack.push(x)
            elif command == "pop":
                stack.pop()
            elif command == "peek":
                stack.peek()
            elif command == "quit":
                break
        except (ValueError, IndexError):
            print("Invalid input.")


if __name__ == "__main__":
    main()
