sub orderByNums {
  my ($nums_ref) = @_; # Receive the array as a reference.  Crucial in Perl for modifying the original array.

  my @nums = @{$nums_ref}; # Dereference the array reference to work with a copy.  This is best practice; avoid modifying the original passed-in data unless explicitly desired.

  my $len = scalar(@nums); # Get the length of the array.  'scalar' ensures we get a numeric count.

  # Outer loop: iterates through the array from the beginning to the second-to-last element.
  for (my $i = 0; $i < $len - 1; $i++) {
    # Inner loop: iterates through the array from the current outer loop index to the last element.
    for (my $j = 0; $j < $len - 1; $j++) {
      # The core comparison logic.  It checks if the current element is greater than the next element,
      # OR if the current element is equal to the next element AND the current element appears earlier
      # in the original array (determined by its last index).
      if (($nums[$j] > $nums[$j + 1]) || (($nums[$j] == $nums[$j + 1]) && (index(@nums, $nums[$j]) < index(@nums, $nums[$j + 1])))) {
        # Swap the elements at indices $j and $j + 1.
        my $temp = $nums[$j];
        $nums[$j] = $nums[$j + 1];
        $nums[$j + 1] = $temp;
      }
    }
  }

  return @{$nums_ref}; # Return the modified array as a reference.  Consistent with the input type.
}

