from typing import List, Tuple, Dict, Union

class Pessoa:
    def __init__(self, id: int, name: str, age: int):
        self.id = id
        self.name = name
        self.age = age

pessoas: List[Pessoa] = []

def manage_pessoas(actions: List[Tuple[str, Dict[str, Any]]]) -> List[Union[str, None]]:
    results: List[Union[str, None]] = []

    for action, params in actions:
        if action == 'add':
            new_pessoa = Pessoa(id=params['id'], name=params['name'], age=params['age'])
            pessoas.append(new_pessoa)
            results.append(None)
        elif action == 'update':
            pessoa_id_to_update = params['id']
            for pessoa in pessoas:
                if pessoa.id == pessoa_id_to_update:
                    pessoa.name = params['name']
                    pessoa.age = params['age']
                    results.append('Pessoa updated')
                    break
            else:
                results.append('Pessoa not found')

    return results
