import string

def word_frequency_analysis(text):
    """
    Analyzes text, counts word frequencies (ignoring stop words),
    and prints a dictionary of words appearing at least twice.
    """

    stop_words = set(['the', 'and', 'is', 'in', 'at', 'which', 'on', 'for', 'with', 'a', 'an', 'to', 'of', 'it'])
    word_counts = {}
    text = text.lower()
    text = text.translate(str.maketrans('', '', string.punctuation))

    words = text.split()
    for word in words:
        if word not in stop_words:
            if word in word_counts:
                word_counts[word] += 1
            else:
                word_counts[word] = 1

    result = {word: count for word, count in word_counts.items() if count >= 2}
    print(result)

if __name__ == "__main__":
