def count_alphanumeric(input_string):
    """
    Counts the occurrences of each alphanumeric character in a string,
    ignoring case and preserving order of first appearance.
    """
    char_counts = {}
    for char in input_string:
        if char.isalnum():
            lower_char = char.lower()
            if lower_char in char_counts:
                char_counts[lower_char] += 1
            else:
                char_counts[lower_char] = 1

    for char, count in char_counts.items():
        print(f"{char}: {count}")

if __name__ == "__main__":
    input_string = input()
    count_alphanumeric(input_string)
