import json
from datetime import datetime

posts = []
id_counter = 1

def create_post(title, content, author):
    global id_counter
    date = datetime.utcnow().isoformat()
    post = {"id": id_counter, "title": title, "content": content, "author": author, "date": date}
    posts.append(post)
    id_counter += 1
    return post

def read_post(id):
    for post in posts:
        if post["id"] == id:
            return post
    return {}

def read_all_posts():
    return posts

def update_post(id, title, content, author):
    for post in posts:
        if post["id"] == id:
            date = datetime.utcnow().isoformat()
            post["title"] = title
            post["content"] = content
            post["author"] = author
            post["date"] = date
            return post
    return {}

def delete_post(id):
    global posts
    original_length = len(posts)
    posts = [post for post in posts if post["id"] != id]
    return {} if len(posts) == original_length else {}


n = int(input())

for _ in range(n):
    command = input().split()
    if command[0] == "CREATE":
        title = " ".join(command[1:2])
        content = " ".join(command[2:3])
        author = command[3]
        print(json.dumps(create_post(title, content, author)))
    elif command[0] == "READALL":
        print(json.dumps(read_all_posts()))
    elif command[0] == "READ":
        id = int(command[1])
        print(json.dumps(read_post(id)))
    elif command[0] == "UPDATE":
        id = int(command[1])
        title = " ".join(command[2:3])
        content = " ".join(command[3:4])
        author = command[4]
        print(json.dumps(update_post(id, title, content, author)))
    elif command[0] == "DELETE":
        id = int(command[1])
        print(json.dumps(delete_post(id)))
```

The Python program implements a blog post management system with CRUD operations. It utilizes a list named `posts` to store blog post data, each post represented as a dictionary.  An `id_counter` ensures unique IDs for new posts, assigned sequentially starting from 1.

The functions `create_post`, `read_post`, `read_all_posts`, `update_post`, and `delete_post` handle the respective operations. `create_post` adds a new post to the `posts` list, automatically generating a date string using `datetime.utcnow().isoformat()`. `read_post` retrieves a post by its ID, returning an empty dictionary if not found. `read_all_posts` returns the entire `posts` list. `update_post` modifies an existing post and returns the updated post; it returns an empty dictionary if the ID is not found. `delete_post` removes a post by its ID and returns an empty dictionary regardless of whether the post existed.

The main part of the program reads commands from standard input, parses them, and calls the appropriate function. The results are formatted as JSON using `json.dumps()` and printed to standard output.
